import{_ as a,o as i,c as l,ag as e,j as r}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"12.3 多媒体数据与图像容量 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"12-数学与多媒体/03-多媒体与图像容量.md","filePath":"12-数学与多媒体/03-多媒体与图像容量.md"}'),s={name:"12-数学与多媒体/03-多媒体与图像容量.md"},d={class:"fig"},n={"data-figure-id":"figure-53",viewBox:"0 0 720 244",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"位图容量载体图：左侧四列三行的像素网格，宽对应每行格子数、高对应行数；其中一格被放大到右侧，格内装着 24 位颜色编码，分为红绿蓝各 8 位三组；底部给出缩略算式，格数乘以每格位数再除以 8 即字节数"};function o(x,t,h,c,y,g){return i(),l("div",null,[t[2]||(t[2]=e('<h1 id="_12-3-多媒体数据与图像容量-★★★" tabindex="-1">12.3 多媒体数据与图像容量 ★★★ <a class="header-anchor" href="#_12-3-多媒体数据与图像容量-★★★" aria-label="Permalink to &quot;12.3 多媒体数据与图像容量 ★★★&quot;">​</a></h1><p>现实中的声音和图像多是连续信号，计算机要经过三步：</p><ol><li><strong>采样</strong>：在时间或空间上取点；</li><li><strong>量化</strong>：把每个样本映射为有限等级；</li><li><strong>编码</strong>：用二进制表示量化结果。</li></ol><p>质量与数据量的基本矛盾：采样越密、量化位数越多，通常越接近原信号，但存储与传输开销越大。</p><p>所有原始容量题都可用同一个思路：</p><p><strong>样本个数 × 每个样本的 bit 数 ÷ 8 = Byte 数</strong></p><p>图像的样本是像素，音频的样本是每个声道每次采样值，视频则是在时间上连续出现的图像帧。</p><p>单位必须统一：</p><ul><li><code>1 B=8 bit</code>；</li><li><code>1 KiB=1024 B</code>，<code>1 MiB=1024 KiB=2^20 B</code>；</li><li><strong>卷面对齐</strong>：软考卷面里的 <strong>MB 通常也按 1024 换算</strong>，即 <code>1 MB=1024 KB=2²⁰ B</code>——数值上与本课的 MiB 完全一致，只是叫法不同，做题直接用 1024 换即可，不必纠结 MB/MiB 的拼写区分；</li><li>存储题若明确使用 KB/MB 的十进制定义，则按题面；未说明的传统软考计算通常按 1024 换算；</li><li>传输速率的 kb/s、Mb/s 常按 1000 进位，仍以题面为准。</li></ul><p><strong>应试动作</strong>：计算式最后写出单位。先得到 bit，再除以 8 变 Byte；只有题目要求 KiB/MiB 时才继续除以 1024。</p><hr><h2 id="第七节-图像容量与分辨率-★★★" tabindex="-1">第七节 图像容量与分辨率 ★★★ <a class="header-anchor" href="#第七节-图像容量与分辨率-★★★" aria-label="Permalink to &quot;第七节 图像容量与分辨率 ★★★&quot;">​</a></h2><h3 id="_7-1-位图容量公式" tabindex="-1">7.1 位图容量公式 <a class="header-anchor" href="#_7-1-位图容量公式" aria-label="Permalink to &quot;7.1 位图容量公式&quot;">​</a></h3><p>未压缩位图容量：</p><p><strong>容量(bit)=水平像素×垂直像素×每像素位数</strong></p><p><strong>容量(Byte)=水平像素×垂直像素×位深÷8</strong></p><p>公式里三个乘数各自&quot;住在&quot;图像的哪里？先看一张 4×3 的迷你位图（每个格子=一个像素，格子里装着这格颜色的编码）：</p>',17)),r("figure",d,[(i(),l("svg",n,[...t[0]||(t[0]=[e('<text class="tt" x="20" y="22">一张图 = 一格一格的颜色编码；三个乘数各指一处</text><text class="mt" x="76" y="42">水平像素 = 每行 4 格（宽）</text><text class="mt" x="20" y="128" transform="rotate(-90 28 130)">垂直像素 = 3 行（高）</text><rect class="px" x="46" y="52" width="46" height="46"></rect><rect class="pick" x="92" y="52" width="46" height="46"></rect><rect class="tint" x="138" y="52" width="46" height="46"></rect><rect class="px" x="184" y="52" width="46" height="46"></rect><rect class="tint" x="46" y="98" width="46" height="46"></rect><rect class="px" x="92" y="98" width="46" height="46"></rect><rect class="px" x="138" y="98" width="46" height="46"></rect><rect class="tint" x="184" y="98" width="46" height="46"></rect><rect class="px" x="46" y="144" width="46" height="46"></rect><rect class="tint" x="92" y="144" width="46" height="46"></rect><rect class="px" x="138" y="144" width="46" height="46"></rect><rect class="px" x="184" y="144" width="46" height="46"></rect><path class="zz" d="M138 52 L286 52 M138 98 L286 98"></path><text class="lbl" x="300" y="42">把放大这格拆开：位深 24 位 = R、G、B 各 8 位</text><rect class="g8" x="286" y="56" width="136" height="38"></rect><g stroke="var(--line)" stroke-width="1"><line x1="303" y1="56" x2="303" y2="94"></line><line x1="320" y1="56" x2="320" y2="94"></line><line x1="337" y1="56" x2="337" y2="94"></line><line x1="354" y1="56" x2="354" y2="94"></line><line x1="371" y1="56" x2="371" y2="94"></line><line x1="388" y1="56" x2="388" y2="94"></line><line x1="405" y1="56" x2="405" y2="94"></line></g><text class="lbl" x="354" y="112">R：8 bit</text><rect class="g8" x="426" y="56" width="136" height="38"></rect><g stroke="var(--line)" stroke-width="1"><line x1="443" y1="56" x2="443" y2="94"></line><line x1="460" y1="56" x2="460" y2="94"></line><line x1="477" y1="56" x2="477" y2="94"></line><line x1="494" y1="56" x2="494" y2="94"></line><line x1="511" y1="56" x2="511" y2="94"></line><line x1="528" y1="56" x2="528" y2="94"></line><line x1="545" y1="56" x2="545" y2="94"></line></g><text class="lbl" x="494" y="112">G：8 bit</text><rect class="g8" x="566" y="56" width="136" height="38"></rect><g stroke="var(--line)" stroke-width="1"><line x1="583" y1="56" x2="583" y2="94"></line><line x1="600" y1="56" x2="600" y2="94"></line><line x1="617" y1="56" x2="617" y2="94"></line><line x1="634" y1="56" x2="634" y2="94"></line><line x1="651" y1="56" x2="651" y2="94"></line><line x1="668" y1="56" x2="668" y2="94"></line><line x1="685" y1="56" x2="685" y2="94"></line></g><text class="lbl" x="634" y="112">B：8 bit</text><text class="mt" x="286" y="140">每一小竖格 = 1 个 bit；12 个格子的位深都是 24，只是装的 0/1 不同</text><text class="mt" x="46" y="212">照图算缩略例：容量 = 4 × 3 格 × 24 bit ÷ 8 = 36 B。</text><text class="mt" x="46" y="232">下面的真题算例只是把&quot;4×3 格&quot;换成&quot;1024×768 格&quot;，把&quot;24 位/格&quot;保持不动——公式、图、算式三处同一个道理。</text>',29)])])),t[1]||(t[1]=r("figcaption",null,'宽度是"每行几格"、高度是"几行"、位深是"每格里面装几行 0/1"——三个乘数分别数的是图、行、格内编码。',-1))]),t[3]||(t[3]=e('<p>例：一幅 <code>1024×768</code>、24 bit 真彩色图像：</p><ol><li>像素数=<code>1024×768=786432</code>；</li><li>bit 数=<code>786432×24=18874368 bit</code>；</li><li>Byte 数=<code>18874368/8=2359296 B</code>；</li><li>MiB=<code>2359296/2^20=2.25 MiB</code>。</li></ol><p>第二种方法：24 bit=3 B/像素，直接算 <code>1024×768×3=2359296 B=2.25 MiB</code>，一致。</p><p><strong>反例前置</strong>：24 bit 不是 24 Byte。位深以 bit 表示，每像素 24 bit=3 Byte，漏除以 8 会把容量放大 8 倍。</p><h3 id="_7-2-颜色数与位深" tabindex="-1">7.2 颜色数与位深 <a class="header-anchor" href="#_7-2-颜色数与位深" aria-label="Permalink to &quot;7.2 颜色数与位深&quot;">​</a></h3><p>b bit 最多表示：</p><p><strong>颜色数 = 2^b</strong></p><p>反过来，要表示 N 种颜色，至少需要：</p><p><strong>b=⌈log2N⌉ bit</strong></p><p>常见对应：</p><table tabindex="0"><thead><tr><th style="text-align:right;">位深</th><th style="text-align:right;">最多颜色数</th></tr></thead><tbody><tr><td style="text-align:right;">1 bit</td><td style="text-align:right;">2</td></tr><tr><td style="text-align:right;">4 bit</td><td style="text-align:right;">16</td></tr><tr><td style="text-align:right;">8 bit</td><td style="text-align:right;">256</td></tr><tr><td style="text-align:right;">16 bit</td><td style="text-align:right;">65536</td></tr><tr><td style="text-align:right;">24 bit</td><td style="text-align:right;">2^24≈1677 万</td></tr></tbody></table><p>例：至少表示 300 种颜色。8 bit 只能表示 256 种，不够；9 bit 可表示 512 种，因此至少 9 bit。</p><h3 id="_7-3-像素分辨率与-dpi" tabindex="-1">7.3 像素分辨率与 DPI <a class="header-anchor" href="#_7-3-像素分辨率与-dpi" aria-label="Permalink to &quot;7.3 像素分辨率与 DPI&quot;">​</a></h3><ul><li><code>1920×1080</code>：数字图像的像素尺寸；</li><li>DPI/PPI：每英寸点数/像素数，常用于打印或显示密度；</li><li>打印尺寸（英寸）= 像素数 / PPI。</li></ul><p>例：一幅 3000×2400 像素的图片按 300 PPI 打印，尺寸为 <code>3000/300=10</code> 英寸 × <code>2400/300=8</code> 英寸。</p><p><strong>反例</strong>：只改图片元数据中的 DPI、不改变像素数，通常不会改变未压缩像素数据量；容量公式仍看像素总数和位深。</p><h3 id="_7-4-位图与矢量图" tabindex="-1">7.4 位图与矢量图 <a class="header-anchor" href="#_7-4-位图与矢量图" aria-label="Permalink to &quot;7.4 位图与矢量图&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>位图（Raster/Bitmap）</th><th>矢量图（Vector）</th></tr></thead><tbody><tr><td>表示</td><td>像素阵列</td><td>几何对象与参数</td></tr><tr><td>放大</td><td>会出现锯齿/像素化</td><td>可无级缩放</td></tr><tr><td>擅长</td><td>照片、复杂纹理</td><td>图标、工程图、字体</td></tr><tr><td>容量影响</td><td>分辨率、位深</td><td>对象数量与复杂度</td></tr></tbody></table><p><strong>应试动作</strong>：图像容量先写“宽×高×位深÷8”；颜色数用 2^b；打印题用像素÷PPI。</p><hr>',20))])}const b=a(s,[["render",o]]);export{_ as __pageData,b as default};
